<"'!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="color-scheme" content="light">
  <title>After the Name</title>
  <style>
    :root { color-scheme: light; --paper: #f1eee7; --ink: #23231f; --quiet: #77766f; --rule: #c9c5ba; --red: #bd412d; }
    * { box-sizing: border-box; }
    body { margin: 0; background: var(--paper); color: var(--ink); }
    main { min-height: 100svh; width: min(100% - 3rem, 920px); margin: auto; padding: clamp(1.5rem, 5vw, 4rem) 0; display: flex; flex-direction: column; }
    header, footer { display: flex; justify-content: space-between; gap: 1rem; font: .68rem/1.4 "Courier New", monospace; letter-spacing: .12em; text-transform: uppercase; color: var(--quiet); }
    header { border-bottom: 1px solid var(--rule); padding-bottom: .8rem; }
    article { width: min(100%, 720px); margin: auto; padding: 4rem 0; }
    h1 { margin: 0 0 2.5rem; font: 400 clamp(2.8rem, 7vw, 6rem)/.95 Georgia, serif; letter-spacing: -.04em; }
    .credit { margin: 0 0 3rem; font: clamp(1.1rem, 2.6vw, 1.8rem)/1.5 "Courier New", monospace; }
    .field { height: clamp(12rem, 34vw, 21rem); border-top: 1px solid var(--rule); border-bottom: 1px solid var(--rule); position: relative; overflow: hidden; }
    .dash { position: absolute; top: 50%; left: 0; width: 1.2rem; height: 2px; margin-top: -1px; background: var(--red); opacity: 0; }
    .field.running .dash { opacity: 1; animation: cross 5s linear forwards; }
    @keyframes cross { from { transform: translateX(0); } to { transform: translateX(calc(100% - 1.2rem)); } }
    .prompt { min-height: 1.5em; margin: 1.4rem 0 0; color: var(--quiet); font: .78rem/1.5 "Courier New", monospace; }
    button { display: block; margin: 1rem 0 0 auto; padding: .65rem .9rem; border: 1px solid var(--ink); background: transparent; color: var(--ink); font: .68rem/1.4 "Courier New", monospace; letter-spacing: .08em; text-transform: uppercase; cursor: pointer; }
    button:hover, button:focus-visible { background: var(--ink); color: var(--paper); }
    button:disabled { border-color: var(--rule); color: var(--quiet); background: transparent; cursor: default; }
    .source { margin: 2rem 0 0; color: var(--quiet); font: .7rem/1.6 "Courier New", monospace; }
    .source a { color: inherit; text-underline-offset: .2em; }
    footer { border-top: 1px solid var(--rule); padding-top: .8rem; }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
    @media (max-width: 520px) { main { width: min(100% - 2rem, 480px); } article { padding: 3rem 0; } footer span:last-child { text-align: right; } }
    @media (prefers-reduced-motion: reduce) { .field.running .dash { animation-duration: 5s; } }
  </style>
</head>
<body>
  <main>
    <header><span>The Missing Line / Study</span><span>11 October 2026</span></header>
    <article>
      <h1>After the name</h1>
      <p class="credit" id="credit">Keanu Reeves - John Wick /<br>Jardani Jovonovich</p>
      <div class="field" id="field" role="img" aria-label="An empty ruled field." aria-busy="false"><span class="dash" aria-hidden="true"></span></div>
      <p class="prompt" id="prompt">Read the credit above. When the last name is done, begin the rest.</p>
      <button id="begin" type="button">Begin the rest</button>
      <p class="source">No voice is generated or recorded. The page times only the five seconds after the name. <a href="score-for-a-credit.html">Read the score</a>.</p>
      <p class="sr-only" id="status" role="status" aria-live="polite"></p>
    </article>
    <footer><span>A timed field</span><span>No transcript</span></footer>
  </main>
  <script>
    const field = document.getElementById('"'field');
    const credit = document.getElementById('credit');
    const prompt = document.getElementById('prompt');
    const begin = document.getElementById('begin');
    const status = document.getElementById('status');

    begin.addEventListener('click', () => {
      credit.hidden = true;
      prompt.textContent = '';
      field.classList.remove('running');
      void field.offsetWidth;
      field.setAttribute('aria-busy', 'true');
      field.classList.add('running');
      begin.disabled = true;
      begin.textContent = 'Five seconds';
      status.textContent = 'The five-second rest has begun.';
      window.setTimeout(() => {
        field.classList.remove('running');
        field.setAttribute('aria-busy', 'false');
        begin.disabled = false;
        begin.textContent = 'Begin again';
        credit.hidden = false;
        status.textContent = 'The rest is over. No dialogue was supplied.';
      }, 5000);
    });
  </script>
</body>
</html>
